<?php $e = static fn (mixed $v): string => htmlspecialchars((string) $v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); ?>
<section class="content-container"><h1>Obieg dokumentów</h1><p>Dostępne zmiany robocze. Każda decyzja dotyczy wskazanej rewizji; kolejny zapis rozpoczyna nowy obieg.</p><div class="card panel table-scroll"><table><thead><tr><th>Dokument</th><th>Rewizja</th><th>Stan</th><th>Ostatni zapis</th></tr></thead><tbody><?php foreach ($pages as $page): ?><tr><td><a href="/spaces/<?= rawurlencode($page['space_key']) ?>/pages/<?= rawurlencode($page['slug']) ?>/review"><?= $e($page['title']) ?></a></td><td><?= (int) $page['version'] ?></td><td><?= $e(\OpenWiki\Wiki\PageReviewService::STATES[$page['workflow_state']]) ?></td><td><?= $e($page['updated_at']) ?></td></tr><?php endforeach; ?><?php if ($pages === []): ?><tr><td colspan="4">Brak dostępnych dokumentów w obiegu.</td></tr><?php endif; ?></tbody></table></div><a href="/knowledge/overdue">Dokumenty po terminie przeglądu</a></section>
